#!/usr/bin/env node
// Cut Bunny part sheets (`bunny_rig.PNG`, `bunny_ear.PNG`) into individual
// transparent-background PNGs.
//
// ── Background removal ─────────────────────────────────────────────────
// The two source sheets were generated by GPT Image 2 and look like they
// have transparent backgrounds — but they're actually 3-channel RGB PNGs
// where the "transparent checkerboard" is painted into pixels:
//   light cell ≈ #fefefe  (1.00 luminance)
//   dark cell  ≈ #f4f4f4  (0.96 luminance)
// Cells are perfectly monochromatic (R==G==B) and very bright. Strategy:
//   1. Per-pixel `bgScore` from monochromaticity + luminance.
//   2. BFS from image edges through pixels with score ≥ 0.95 — only
//      pixels reachable from the outside via a strict-background path
//      are erased. Bunny's white fur is enclosed by coloured edges so
//      flood fill can't sneak inside it even when fur tips happen to be
//      perfectly white.
//   3. Pixels adjacent to a reachable region get partial alpha from
//      score, giving anti-aliased edges instead of hard cliffs.
//
// ── Naming ─────────────────────────────────────────────────────────────
// We DON'T do row-grouping (ears span multiple visual rows and break it).
// Instead, classify each component by intrinsic features:
//
//   `bunny_rig.PNG` (1254×1254) actual layout, 17 components:
//      Top band:   head, body, paw_a, paw_b               (4)
//      Mid band:   ear_pink, ear_rainbow                  (2, very tall)
//                  eye_open ×2, eye_closed ×2             (4, contains brown/dark)
//                  mouth ×4 (closed → wide)               (4, white blob with pink nose)
//      Bot band:   cheek_left, cheek_right, flower        (3, pink-dominant)
//
//   `bunny_ear.PNG` (1254×1254): 6 ear-pose variants. Numbered 01..06
//     in reading order (top-to-bottom rows, then left-to-right).
//
// Classification keys per component:
//   - bbox + centroid + area
//   - aspect ratio h/w
//   - average colour of opaque pixels
//   - "pinkness" (R - average(G,B)) and "darkness" (count of pixels with
//     luminance < 100 — used to spot eye irises and lashes vs white blobs)
//
// Output: `public/assets/bunny/parts/<name>.png` plus
//         `public/assets/bunny/parts/_debug/<sheet>_alpha.png` (full
//         alpha-keyed sheet) and
//         `public/assets/bunny/parts/_debug/<sheet>_annotated.png`
//         (the alpha sheet with bbox + label drawn on each component —
//         lets you eyeball whether classification matches reality).
//
// Run:  node scripts/cut-bunny-parts.mjs

import sharp from "sharp";
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const ASSET_DIR = path.join(ROOT, "public/assets/bunny");
const OUT_DIR = path.join(ASSET_DIR, "parts");
const DEBUG_DIR = path.join(OUT_DIR, "_debug");

// ── Tuning ──────────────────────────────────────────────────────────────
const STRICT_BG_SCORE = 0.95;
const ANY_BG_SCORE = 0.10;
const ALPHA_KEEP = 16;
const MIN_COMPONENT_AREA = 800;
const PAD = 8;
// ────────────────────────────────────────────────────────────────────────

function bgScore(r, g, b) {
  const maxC = Math.max(r, g, b);
  const minC = Math.min(r, g, b);
  const chroma = maxC - minC;
  const lum = (r + g + b) / 3;
  if (chroma <= 2 && lum >= 240) return 1.0;
  if (chroma <= 5 && lum >= 232) {
    const lumScore = Math.min(1, (lum - 232) / 22);
    const chromaScore = Math.max(0, 1 - chroma / 5);
    return lumScore * chromaScore * 0.85;
  }
  return 0;
}

async function buildAlpha(srcPath) {
  const { data, info } = await sharp(srcPath)
    .ensureAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });
  const W = info.width, H = info.height, N = W * H;
  if (info.channels !== 4) {
    throw new Error(`Expected RGBA, got channels=${info.channels}`);
  }

  const score = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    score[i] = bgScore(data[i * 4], data[i * 4 + 1], data[i * 4 + 2]);
  }

  const reachable = new Uint8Array(N);
  const queue = new Int32Array(N);
  let qHead = 0, qTail = 0;
  const seed = (idx) => {
    if (!reachable[idx] && score[idx] >= STRICT_BG_SCORE) {
      reachable[idx] = 1; queue[qTail++] = idx;
    }
  };
  for (let x = 0; x < W; x++) { seed(x); seed((H - 1) * W + x); }
  for (let y = 0; y < H; y++) { seed(y * W); seed(y * W + (W - 1)); }
  while (qHead < qTail) {
    const idx = queue[qHead++];
    const x = idx % W, y = (idx / W) | 0;
    if (x > 0)     { const n = idx - 1; if (!reachable[n] && score[n] >= STRICT_BG_SCORE) { reachable[n] = 1; queue[qTail++] = n; } }
    if (x < W - 1) { const n = idx + 1; if (!reachable[n] && score[n] >= STRICT_BG_SCORE) { reachable[n] = 1; queue[qTail++] = n; } }
    if (y > 0)     { const n = idx - W; if (!reachable[n] && score[n] >= STRICT_BG_SCORE) { reachable[n] = 1; queue[qTail++] = n; } }
    if (y < H - 1) { const n = idx + W; if (!reachable[n] && score[n] >= STRICT_BG_SCORE) { reachable[n] = 1; queue[qTail++] = n; } }
  }

  const out = Buffer.allocUnsafe(N * 4);
  data.copy(out);
  for (let i = 0; i < N; i++) {
    if (reachable[i]) { out[i * 4 + 3] = 0; continue; }
    const s = score[i];
    if (s > ANY_BG_SCORE) {
      const x = i % W, y = (i / W) | 0;
      let edge = false;
      for (let dy = -1; dy <= 1 && !edge; dy++) {
        for (let dx = -1; dx <= 1 && !edge; dx++) {
          if (!dx && !dy) continue;
          const nx = x + dx, ny = y + dy;
          if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue;
          if (reachable[ny * W + nx]) edge = true;
        }
      }
      if (edge) { out[i * 4 + 3] = Math.round(255 * (1 - s)); continue; }
    }
    out[i * 4 + 3] = 255;
  }
  return { width: W, height: H, rgba: out };
}

function findComponents({ width: W, height: H, rgba }) {
  const N = W * H;
  const fg = new Uint8Array(N);
  for (let i = 0; i < N; i++) fg[i] = rgba[i * 4 + 3] > ALPHA_KEEP ? 1 : 0;

  const labels = new Int32Array(N);
  const parent = [0];
  let next = 1;
  const find = (a) => { while (parent[a] !== a) { parent[a] = parent[parent[a]]; a = parent[a]; } return a; };
  const union = (a, b) => { const ra = find(a), rb = find(b); if (ra !== rb) parent[Math.max(ra, rb)] = Math.min(ra, rb); };

  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = y * W + x;
      if (!fg[i]) continue;
      const left  = x > 0 ? labels[i - 1] : 0;
      const above = y > 0 ? labels[i - W] : 0;
      if (left && above)      { labels[i] = Math.min(left, above); union(left, above); }
      else if (left)           labels[i] = left;
      else if (above)          labels[i] = above;
      else                    { labels[i] = next; parent[next] = next; next++; }
    }
  }

  const map = new Map();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const lab = labels[y * W + x];
      if (!lab) continue;
      const root = find(lab);
      const b = map.get(root);
      if (!b) {
        map.set(root, { x0: x, y0: y, x1: x, y1: y, area: 1 });
      } else {
        if (x < b.x0) b.x0 = x; if (y < b.y0) b.y0 = y;
        if (x > b.x1) b.x1 = x; if (y > b.y1) b.y1 = y;
        b.area++;
      }
    }
  }
  return [...map.values()].filter((b) => b.area >= MIN_COMPONENT_AREA);
}

// Add classification stats to each component.
function profileComponent(c, sheet) {
  const { width: W, rgba } = sheet;
  let rs = 0, gs = 0, bs = 0, n = 0, dark = 0, brown = 0;
  for (let y = c.y0; y <= c.y1; y++) {
    for (let x = c.x0; x <= c.x1; x++) {
      const i = (y * W + x) * 4;
      if (rgba[i + 3] <= 200) continue;
      const r = rgba[i], g = rgba[i + 1], b = rgba[i + 2];
      rs += r; gs += g; bs += b; n++;
      const lum = (r + g + b) / 3;
      if (lum < 100) dark++;
      // Brown iris: warm midtone (R > G > B, lum 70-160)
      if (r > g && g > b && r - b > 25 && lum > 50 && lum < 170) brown++;
    }
  }
  c.cx = (c.x0 + c.x1) / 2;
  c.cy = (c.y0 + c.y1) / 2;
  c.w = c.x1 - c.x0 + 1;
  c.h = c.y1 - c.y0 + 1;
  c.aspect = c.h / c.w;
  c.avg = n ? { r: rs / n, g: gs / n, b: bs / n } : { r: 0, g: 0, b: 0 };
  c.darkRatio = n ? dark / n : 0;
  c.brownRatio = n ? brown / n : 0;
  c.pinkness = c.avg.r - (c.avg.g + c.avg.b) / 2; // > 0 → pink/warm
  c.whiteness = Math.min(c.avg.r, c.avg.g, c.avg.b); // 0..255, high = white
  c.colorRange = (() => {
    // Approximate hue spread: difference between max R-B variance over the bbox
    // (simple heuristic — rainbow ear has wide spread, monochrome pink doesn't)
    let minR = 255, maxR = 0, minB = 255, maxB = 0;
    for (let y = c.y0; y <= c.y1; y += 4) {
      for (let x = c.x0; x <= c.x1; x += 4) {
        const i = (y * W + x) * 4;
        if (rgba[i + 3] <= 200) continue;
        const r = rgba[i], b = rgba[i + 2];
        if (r < minR) minR = r; if (r > maxR) maxR = r;
        if (b < minB) minB = b; if (b > maxB) maxB = b;
      }
    }
    return (maxR - minR) + (maxB - minB);
  })();
  return c;
}

function summary(c) {
  return `(${c.cx | 0},${c.cy | 0}) ${c.w}×${c.h} a=${c.area} ar=${c.aspect.toFixed(2)} `
    + `rgb=(${c.avg.r | 0},${c.avg.g | 0},${c.avg.b | 0}) pink=${c.pinkness.toFixed(0)} `
    + `dark=${(c.darkRatio * 100).toFixed(1)}% brown=${(c.brownRatio * 100).toFixed(1)}% `
    + `range=${c.colorRange | 0}`;
}

// ── Naming for `bunny_rig.PNG` ─────────────────────────────────────────
//
// Naming strategy:
//   1. Pull out ears first (very tall: aspect > 1.5, area > 30k). Pink vs
//      rainbow distinguished by colour spread (rainbow has wider range).
//   2. On the remaining 15 components, cluster by Y centroid using a gap
//      threshold (gap > 100 px starts a new cluster). The rig sheet's
//      layout produces 4 distinct Y bands once ears are removed:
//        · top:    head, body, paw_a, paw_b (4)
//        · eyes:   2 open + 2 closed         (4)
//        · mouths: closed → wide             (4)
//        · bottom: 2 cheek swirls + flower   (3)
//   3. Within each cluster, classify by intrinsic features:
//        · top: 2 largest = head/body (left/right by cx). Rest = paws,
//          ordered by cy (upper = a, lower = b).
//        · eyes: aspect > 0.8 = open (roundish), aspect ≤ 0.7 = closed
//          (flat lash line). Order by cx.
//        · mouths: order by cx (closed → small → mid → wide).
//        · bottom: largest = flower. Other two = cheeks (left/right by cx).
//
function nameRig(components, sheet) {
  for (const c of components) profileComponent(c, sheet);
  const named = new Map();
  const warns = [];
  const take = (name, c, why) => named.set(name, { c, why });

  // 1. Ears.
  const earCandidates = components
    .filter((c) => c.aspect > 1.5 && c.area > 30000)
    .sort((a, b) => b.area - a.area);
  if (earCandidates.length !== 2) warns.push(`Ear candidates: ${earCandidates.length}, expected 2`);
  const ears = earCandidates.slice(0, 2);
  const earSet = new Set(ears);
  if (ears.length === 2) {
    const rainbow = ears[0].colorRange > ears[1].colorRange ? ears[0] : ears[1];
    const pink = rainbow === ears[0] ? ears[1] : ears[0];
    take("ear_pink", pink, `tall, colour range ${pink.colorRange | 0}`);
    take("ear_rainbow", rainbow, `tall, colour range ${rainbow.colorRange | 0}`);
  }

  // 2. Y-gap cluster the remaining components.
  const rest = components.filter((c) => !earSet.has(c)).sort((a, b) => a.cy - b.cy);
  const clusters = rest.length ? [[rest[0]]] : [];
  const Y_GAP = 100;
  for (let i = 1; i < rest.length; i++) {
    if (rest[i].cy - rest[i - 1].cy > Y_GAP) clusters.push([rest[i]]);
    else clusters[clusters.length - 1].push(rest[i]);
  }
  if (clusters.length !== 4) {
    warns.push(`Y clusters: ${clusters.length}, expected 4 (sizes: ${clusters.map((c) => c.length).join(",")})`);
  }

  // 3a. Top cluster → head, body, paws.
  const top = clusters[0] || [];
  const topBySize = [...top].sort((a, b) => b.area - a.area);
  const big2 = topBySize.slice(0, 2).sort((a, b) => a.cx - b.cx);
  if (big2[0]) take("head", big2[0], `top cluster, large, leftmost (a=${big2[0].area})`);
  if (big2[1]) take("body", big2[1], `top cluster, large, 2nd (a=${big2[1].area})`);
  const paws = topBySize.slice(2).sort((a, b) => a.cy - b.cy);
  if (paws[0]) take("paw_a", paws[0], `top cluster, small, upper (cy=${paws[0].cy | 0})`);
  if (paws[1]) take("paw_b", paws[1], `top cluster, small, lower (cy=${paws[1].cy | 0})`);
  if (top.length !== 4) warns.push(`Top cluster: ${top.length}, expected 4 (head/body/paw×2)`);

  // 3b. Eyes cluster → 2 open (round) + 2 closed (flat lashes).
  const eyes = clusters[1] || [];
  const opens = eyes.filter((c) => c.aspect > 0.8).sort((a, b) => a.cx - b.cx);
  const closeds = eyes.filter((c) => c.aspect <= 0.8).sort((a, b) => a.cx - b.cx);
  if (opens[0])    take("eye_open_left",    opens[0],    `aspect ${opens[0].aspect.toFixed(2)} (round)`);
  if (opens[1])    take("eye_open_right",   opens[1],    `aspect ${opens[1].aspect.toFixed(2)} (round)`);
  if (closeds[0])  take("eye_closed_left",  closeds[0],  `aspect ${closeds[0].aspect.toFixed(2)} (flat)`);
  if (closeds[1]) take("eye_closed_right", closeds[1],  `aspect ${closeds[1].aspect.toFixed(2)} (flat)`);
  if (opens.length !== 2 || closeds.length !== 2) {
    warns.push(`Eye cluster: ${opens.length} open + ${closeds.length} closed, expected 2+2`);
  }

  // 3c. Mouth cluster → 4 mouths, left→right = closed→wide.
  const mouths = (clusters[2] || []).slice().sort((a, b) => a.cx - b.cx);
  const mouthNames = ["mouth_closed", "mouth_small", "mouth_mid", "mouth_wide"];
  for (let i = 0; i < mouths.length && i < mouthNames.length; i++) {
    take(mouthNames[i], mouths[i], `mouth cluster, ${i + 1}/4 by x`);
  }
  if (mouths.length !== 4) warns.push(`Mouth cluster: ${mouths.length}, expected 4`);

  // 3d. Bottom cluster → flower + 2 cheeks.
  const bot = clusters[3] || [];
  const botBySize = [...bot].sort((a, b) => b.area - a.area);
  if (botBySize[0]) take("flower", botBySize[0], `bottom cluster, largest (a=${botBySize[0].area})`);
  const cheeks = botBySize.slice(1).sort((a, b) => a.cx - b.cx);
  if (cheeks[0]) take("cheek_left", cheeks[0], `bottom cluster, small, left (cx=${cheeks[0].cx | 0})`);
  if (cheeks[1]) take("cheek_right", cheeks[1], `bottom cluster, small, right (cx=${cheeks[1].cx | 0})`);
  if (bot.length !== 3) warns.push(`Bottom cluster: ${bot.length}, expected 3 (cheek×2 + flower)`);

  // Anything not classified?
  const namedSet = new Set([...named.values()].map((v) => v.c));
  for (const c of components) {
    if (!namedSet.has(c)) warns.push(`Unclassified: ${summary(c)}`);
  }

  return { named, warns };
}

// ── Naming for `bunny_ear.PNG` ─────────────────────────────────────────
function nameEarPoses(components, sheet) {
  for (const c of components) profileComponent(c, sheet);
  // Group into rows by gap-based Y clustering, then within row sort by X.
  const sorted = [...components].sort((a, b) => a.cy - b.cy);
  const rows = [[sorted[0]]];
  for (let i = 1; i < sorted.length; i++) {
    const prev = sorted[i - 1];
    const cur = sorted[i];
    if (cur.cy - prev.cy > Math.max(prev.h, cur.h) * 0.5) rows.push([cur]);
    else rows[rows.length - 1].push(cur);
  }
  for (const row of rows) row.sort((a, b) => a.cx - b.cx);

  const named = new Map();
  let n = 0;
  for (const row of rows) {
    for (const c of row) {
      n++;
      const name = `ear_pose_${String(n).padStart(2, "0")}`;
      named.set(name, { c, why: `row ${rows.indexOf(row) + 1}, col ${row.indexOf(c) + 1}` });
    }
  }
  return { named, warns: n === 6 ? [] : [`Ear-pose total: ${n}, expected 6`] };
}

async function cropComponent(sheet, c, outPath) {
  const { width: W, height: H, rgba } = sheet;
  const x0 = Math.max(0, c.x0 - PAD);
  const y0 = Math.max(0, c.y0 - PAD);
  const x1 = Math.min(W - 1, c.x1 + PAD);
  const y1 = Math.min(H - 1, c.y1 + PAD);
  const w = x1 - x0 + 1, h = y1 - y0 + 1;
  const sub = Buffer.allocUnsafe(w * h * 4);
  for (let y = 0; y < h; y++) {
    const srcOff = ((y0 + y) * W + x0) * 4;
    rgba.copy(sub, y * w * 4, srcOff, srcOff + w * 4);
  }
  await sharp(sub, { raw: { width: w, height: h, channels: 4 } }).png().toFile(outPath);
  return { w, h };
}

async function saveDebugSheet(sheet, outPath) {
  await sharp(sheet.rgba, { raw: { width: sheet.width, height: sheet.height, channels: 4 } }).png().toFile(outPath);
}

// Annotate the alpha sheet with bbox + label per component.
async function saveAnnotated(sheet, named, outPath) {
  const { width, height } = sheet;
  const svgRects = [];
  for (const [name, { c }] of named) {
    const x = c.x0 - 2, y = c.y0 - 2;
    const w = c.w + 4, h = c.h + 4;
    svgRects.push(
      `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="none" stroke="#ff3366" stroke-width="3"/>` +
      `<rect x="${x}" y="${y - 26}" width="${Math.max(name.length * 9 + 8, 60)}" height="24" fill="#ff3366"/>` +
      `<text x="${x + 4}" y="${y - 8}" font-family="monospace" font-size="14" fill="white">${name}</text>`,
    );
  }
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}">${svgRects.join("")}</svg>`;
  await sharp(sheet.rgba, { raw: { width, height, channels: 4 } })
    .composite([{ input: Buffer.from(svg), top: 0, left: 0 }])
    .png()
    .toFile(outPath);
}

async function processSheet(sheetFile, namer, label) {
  const srcPath = path.join(ASSET_DIR, sheetFile);
  console.log(`\n── ${sheetFile} ────────────────────────────`);
  const sheet = await buildAlpha(srcPath);
  console.log(`  size: ${sheet.width}×${sheet.height}`);

  await saveDebugSheet(sheet, path.join(DEBUG_DIR, `${label}_alpha.png`));

  const components = findComponents(sheet);
  console.log(`  components ≥${MIN_COMPONENT_AREA}px²: ${components.length}`);

  const { named, warns } = namer(components, sheet);
  for (const w of warns) console.warn(`  ⚠ ${w}`);

  const manifest = [];
  for (const [name, { c, why }] of named) {
    const outPath = path.join(OUT_DIR, `${name}.png`);
    const { w, h } = await cropComponent(sheet, c, outPath);
    manifest.push({ name, w, h, area: c.area, cx: c.cx | 0, cy: c.cy | 0, why });
    console.log(`  ✓ ${name.padEnd(20)} ${String(w).padStart(4)}×${String(h).padStart(4)}  ${summary(c)}`);
  }

  await saveAnnotated(sheet, named, path.join(DEBUG_DIR, `${label}_annotated.png`));
  console.log(`  debug: parts/_debug/${label}_alpha.png  +  ${label}_annotated.png`);

  return manifest;
}

async function main() {
  await fs.mkdir(OUT_DIR, { recursive: true });
  await fs.mkdir(DEBUG_DIR, { recursive: true });
  const all = [];
  all.push(...(await processSheet("bunny_rig.PNG", nameRig, "rig")));
  all.push(...(await processSheet("bunny_ear.PNG", nameEarPoses, "ear")));
  await fs.writeFile(
    path.join(OUT_DIR, "_manifest.json"),
    JSON.stringify({ generatedAt: new Date().toISOString(), parts: all }, null, 2),
  );
  console.log(`\n→ ${all.length} parts → public/assets/bunny/parts/`);
}

main().catch((err) => { console.error(err); process.exit(1); });
